// Pull the API response from the previous node
const response = $input.first().json;
const accounts = response.accounts;
const generatedAt = response.generated_at;
const totalScored = response.total_scored;

const today = new Date().toLocaleDateString('en-GB', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

// Format account list for the LLM
const accountLines = accounts.map((a, i) => {
  const signals = a.risk_signals.join('; ');
  return [
    `${i + 1}. ${a.account_name} (${a.industry}, ${a.sub_plan} plan, $${a.mrr}/mo, ${a.seats} seats)`,
    `   Risk score: ${a.risk_score}/100`,
    `   Signals: ${signals || 'no specific signals'}`
  ].join('\n');
}).join('\n\n');

const prompt = `You are a customer success assistant for Ravenstack, a B2B SaaS platform.

Below are this week's top ${accounts.length} at-risk accounts scored by our churn prediction model. For each account, write a single plain-English sentence (maximum 20 words) that a customer success manager can act on immediately. Be specific — name the signal and what it implies for the customer relationship.

Accounts:
${accountLines}

Rules:
- One sentence per account, numbered to match the list above
- No preamble, no headers, no commentary after the list
- Write for a non-technical reader who knows the customer`;

const llmPayload = {
  model: 'claude-sonnet-4-20250514',
  max_tokens: 1000,
  messages: [{ role: 'user', content: prompt }]
};

return [{
  json: {
    accounts,
    generatedAt,
    totalScored,
    today,
    llmPayload
  }
}];

// Access account data from the prompt-building step
const promptData = $('Build LLM Prompt').first().json;
const accounts   = promptData.accounts;
const totalScored = promptData.totalScored;
const today       = promptData.today;

// Parse the LLM response from the current node input
const llmResponse = $input.first().json;
const contentBlocks = llmResponse.content || [];
const rawText = contentBlocks.find(c => c.type === 'text')?.text || '';

// Extract numbered lines from the LLM output
const alertLines = rawText
  .split('\n')
  .map(l => l.trim())
  .filter(l => /^\d+\./.test(l))
  .map(l => l.replace(/^\d+\.\s*/, ''));

// Build Slack Block Kit payload
const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: '🔴 Weekly Churn Risk Digest', emoji: true }
  },
  {
    type: 'context',
    elements: [{
      type: 'mrkdwn',
      text: `*${today}*  ·  ${accounts.length} accounts flagged from ${totalScored} active  ·  Model: rule-based v1`
    }]
  },
  { type: 'divider' }
];

accounts.forEach((acct, i) => {
  // Fall back to the raw signals if the LLM didn't produce a line for this account
  const alert = alertLines[i] || acct.risk_signals.join('; ') || 'Review account history.';

  // Visual risk bar
  const filled = Math.min(Math.round(acct.risk_score / 10), 10);
  const bar    = '▓'.repeat(filled) + '░'.repeat(10 - filled);
  const dot    = acct.risk_score >= 65 ? '🔴' : acct.risk_score >= 40 ? '🟡' : '🟢';

  // Main account row
  blocks.push({
    type: 'section',
    fields: [
      {
        type: 'mrkdwn',
        text: `*${acct.account_name}*\n${acct.sub_plan} · ${acct.seats} seats · $${acct.mrr}/mo · ${acct.country}`
      },
      {
        type: 'mrkdwn',
        text: `${dot} *Score: ${acct.risk_score}/100*\n\`${bar}\``
      }
    ]
  });

  // Alert sentence from LLM
  blocks.push({
    type: 'context',
    elements: [{ type: 'mrkdwn', text: `_${alert}_` }]
  });

  if (i < accounts.length - 1) blocks.push({ type: 'divider' });
});

// Footer instructions for the CS team
blocks.push({ type: 'divider' });
blocks.push({
  type: 'context',
  elements: [{
    type: 'mrkdwn',
    text: '✅ = reached out   ⏭️ = skip this week   💬 = leave note in thread   | Next digest: Monday 08:00'
  }]
});

return [{ json: { blocks } }];
